import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import type { PrimitiveProps } from "../primitives";

const BASE = "#071433";
const DEEP = "#030A1F";
const GLOW = "#1E3A8A";

const DarkBlueStatic: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const t = frame / fps;

  // Slow breathing glow: 0..1..0 every 8s, eased.
  const breathPhase = (t % 8) / 8;
  const breath = interpolate(breathPhase, [0, 0.5, 1], [0, 1, 0], {
    easing: Easing.inOut(Easing.sin),
  });

  // Glow centre drifts on a slow Lissajous path.
  const gx = 50 + Math.sin(t * 0.21) * 18;
  const gy = 42 + Math.cos(t * 0.15) * 14;

  // Static grain: new noise pattern every 2 frames, cycling through 12 seeds.
  const seed = Math.floor(frame / 2) % 12;
  const grainShiftX = ((seed * 37) % 60) - 30;
  const grainShiftY = ((seed * 53) % 80) - 40;

  // Scanlines scroll slowly downward, seamless over a 6px period.
  const scanOffset = (t * 12) % 6;

  // Faint horizontal interference band sweeping top→bottom every 10s.
  const bandY = ((t % 10) / 10) * 2400 - 240;

  return (
    <AbsoluteFill style={{ backgroundColor: BASE, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 60% at ${gx}% ${gy}%, ${GLOW} 0%, ${BASE} 55%, ${DEEP} 100%)`,
          opacity: 0.55 + breath * 0.25,
        }}
      />

      <svg
        width={1200}
        height={2040}
        style={{
          position: "absolute",
          left: -60 + grainShiftX,
          top: -60 + grainShiftY,
          opacity: 0.09,
          mixBlendMode: "screen",
        }}
      >
        <filter id="dark-blue-static-grain">
          <feTurbulence
            type="fractalNoise"
            baseFrequency={0.85}
            numOctaves={2}
            seed={seed}
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#dark-blue-static-grain)" />
      </svg>

      <AbsoluteFill
        style={{
          backgroundImage:
            "repeating-linear-gradient(to bottom, rgba(0,0,0,0.22) 0px, rgba(0,0,0,0.22) 2px, transparent 2px, transparent 6px)",
          backgroundPosition: `0px ${scanOffset}px`,
          opacity: 0.5,
        }}
      />

      <div
        style={{
          position: "absolute",
          left: 0,
          width: "100%",
          height: 240,
          top: bandY,
          background:
            "linear-gradient(to bottom, transparent, rgba(30,58,138,0.18), transparent)",
        }}
      />

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 75% 65% at 50% 50%, transparent 55%, ${DEEP} 100%)`,
          opacity: 0.85,
        }}
      />
    </AbsoluteFill>
  );
};

export default DarkBlueStatic;
